---@class RaceJCPMatchingView : ViewBase
RaceJCPMatchingView = class("RaceJCPMatchingView", ViewBase)

function RaceJCPMatchingView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "RaceJCPMatchingViewAction")

    self.TimerID = -1
    self.Time = -1
end

function RaceJCPMatchingView:Awake()
    CommonHelper:HButtonSetCallback("BtnCancel",self.gameObject,function (hbtn)
        RaceJcpSubsystem:Get():SendMsg_RaceJCPCancel()
        UIManager:Get():HidePersistentView("RaceJCPMatchingView")
    end)
    CommonHelper:HButtonSetCallback("BtnClose",self.gameObject,function (hbtn)
        self:SetUIGroup(false)
    end)
    CommonHelper:HButtonSetCallback("BtnTime",self.gameObject,function (hbtn)
        self:SetUIGroup(true)
    end)

end

function RaceJCPMatchingView:OnOpen()
    self:SetUIGroup(true)
    self:StartTimer()
end

function RaceJCPMatchingView:OnClose()
    self:StopTimer()
end

function RaceJCPMatchingView:SetUIGroup(ismax)
    self.MaxUI = CommonHelper:SetGameObjectActive("max", self.gameObject, ismax)
    self.MinUI = CommonHelper:SetGameObjectActive("min", self.gameObject, not ismax)
end

function RaceJCPMatchingView:SetTime()
    local temp = ClientDataManager:Get():GetTemplateString(TemplateStringID.RaceRankMatchTimeFromat)
    CommonHelper:SetText("###waitingvalue", self.MaxUI, string.format(temp, self.Time))
    CommonHelper:SetText("###waitingvalue", self.MinUI, string.format(temp, self.Time))
end



function RaceJCPMatchingView:StartTimer()
    self:StopTimer()
    self:SetTime()
    self.TimerID = TimerManager:Get():CreateTimerLoop(1, function()
        self:TimerGoing()
    end)
end

function RaceJCPMatchingView:TimerGoing()
    self.Time = self.Time + 1
    self:SetTime()
end

function RaceJCPMatchingView:StopTimer()
    TimerManager:Get():StopTimer(self.TimerID)
    self.TimerID = -1
    self.Time = 1
end